+ *
+ * @param node The node to get JSDoc comments and tags for.
+ * @returns An array of `JSDoc` and `JSDocTag` nodes.
+ */
+export function getJSDocCommentsAndTags(node: Node): (JSDoc | JSDocTag)[] {
+    const result: (JSDoc | JSDocTag)[] = [];
+
+    // Pull parameter comments from a declaring initializer (e.g. `var x = function () {}`).
+    if (isVariableLike(node)) {
+        const initializer = (node as { initializer?: Node; }).initializer;
+        if (initializer) {
+            const initJSDoc = getJSDocNodes(initializer);
+            if (initJSDoc.length) {
+                result.push(...initJSDoc);
+                result.push(...filterOwnedJSDocTags(node, initJSDoc));
+            }
+        }
+    }
+
+    let currentNode: Node | undefined = node;
+    while (currentNode && currentNode.parent) {
+        const jsDocNodes = getJSDocNodes(currentNode);
+        if (jsDocNodes.length) {
+            result.push(...jsDocNodes);
+            result.push(...filterOwnedJSDocTags(node, jsDocNodes));
+        }
+
+        if (currentNode.kind === SyntaxKind.Parameter) {
+            result.push(...getJSDocParameterTags(currentNode as ParameterDeclaration));
+            break;
+        }
+        if (currentNode.kind === SyntaxKind.TypeParameter) {
+            result.push(...getJSDocTypeParameterTags(currentNode as TypeParameterDeclaration));
+            break;
+        }
+        currentNode = getNextJSDocCommentLocation(currentNode);
+    }
+    return result;
+}
