+// fetchMaxNodesPerRead retrieves the server's MaxNodesPerRead limit.
+func (o *readClient) fetchMaxNodesPerRead() (uint32, error) {
+	// NodeID for Server/ServerCapabilities/OperationLimits/MaxNodesPerRead
+	maxNodesPerReadNodeID := ua.MustParseNodeID("ns=0;i=11705")
+	req := &ua.ReadRequest{
+		NodesToRead: []*ua.ReadValueID{
+			{NodeID: maxNodesPerReadNodeID},
+		},
+		TimestampsToReturn: ua.TimestampsToReturnNeither,
+	}
+
+	resp, err := o.Client.Read(o.ctx, req)
+	if err != nil {
+		return 0, fmt.Errorf("failed to read MaxNodesPerRead node: %w", err)
+	}
+	if len(resp.Results) == 0 || resp.Results[0].StatusCode.Error() != nil {
+		return 0, fmt.Errorf("failed to get valid MaxNodesPerRead value: %v", resp.Results[0].StatusCode)
+	}
+
+	// The value should be of type ua.UInt32
+	if maxNodesPerRead, ok := resp.Results[0].Value.Value.(uint32); ok {
+		return maxNodesPerRead, nil
+	}
+
+	return 0, fmt.Errorf("unexpected type for MaxNodesPerRead: %T", resp.Results[0].Value.Value)
 }

